import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../assets/styles/Services.css';

// Local fallback icons
import webDevIcon from '../assets/images/webdev.png';
import backendIcon from '../assets/images/backend.png';
import databaseIcon from '../assets/images/database.png';
import testingIcon from '../assets/images/testing.png';
import financeIcon from '../assets/images/finance.png';

// Map backend icon paths to local images
const iconMap = {
  "/assets/images/webdev.png": webDevIcon,
  "/assets/images/backend.png": backendIcon,
  "/assets/images/database.png": databaseIcon,
  "/assets/images/testing.png": testingIcon,
  "/assets/images/finance.png": financeIcon,
};

const Services = () => {
  const [services, setServices] = useState([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [currentService, setCurrentService] = useState(null);

  const [formData, setFormData] = useState({
    title: "",
    description: ""
  });

  // ✅ Bulletproof admin detection
const role = localStorage.getItem("role");
const token = localStorage.getItem("token");

let isAdmin = false;

// Case 1: role stored directly
if (role === "admin") {
  isAdmin = true;
}

// Case 2: JWT contains role
if (token) {
  try {
    const payload = JSON.parse(atob(token.split(".")[1]));
    if (payload.role === "admin") {
      isAdmin = true;
    }
  } catch (e) {
    console.error("Invalid token");
  }
}


  // ✅ Load services from backend
  useEffect(() => {
    axios
      .get("http://localhost:5000/api/services")
      .then((res) => setServices(res.data))
      .catch((err) => console.error("Error fetching services:", err));
  }, []);

  // ✅ Create Service (always uses default icon)
 const createService = () => {
  axios.post(
    "http://localhost:5000/api/services",
    {
      title: formData.title,
      description: formData.description,
      icon: "/assets/images/webdev.png"
    },
    {
      headers: {
        Authorization: `Bearer ${localStorage.getItem("token")}`
      }
    }
  )
  .then(() => {
    setShowAddModal(false);
    window.location.reload();
  })
  .catch((err) => console.error("Create error:", err.response?.data || err));
};


  // ✅ Open Edit Modal
  const openEditModal = (service) => {
    setCurrentService(service);
    setFormData({
      title: service.title,
      description: service.description
    });
    setShowEditModal(true);
  };
  // ✅ Update Service
  const updateService = () => {
  axios.put(
    `http://localhost:5000/api/services/${currentService._id}`,
    {
      title: formData.title,
      description: formData.description,
      icon: currentService.icon
    },
    {
      headers: {
        Authorization: `Bearer ${localStorage.getItem("token")}`
      }
    }
  )
  .then(() => {
    setShowEditModal(false);
    window.location.reload();
  })
  .catch((err) => console.error("Update error:", err.response?.data || err));
};


    // ✅ Delete Service
  const deleteService = (id) => {
    if (!window.confirm("Delete this service?")) return;

   axios.delete(
  `http://localhost:5000/api/services/${id}`,
  {
    headers: {
      Authorization: `Bearer ${localStorage.getItem("token")}`
    }
  }
)

      .then(() => window.location.reload())
      .catch((err) => console.error(err));
  };

  return (
    <div className="services">
      <h1>My Services</h1>

      {/* ✅ Admin-only Add button */}
      {isAdmin && (
        <button className="add-btn" onClick={() => setShowAddModal(true)}>
          + Add Service
        </button>
      )}

      <div className="service-list">
        {services.map((service) => (
          <div className="service-card" key={service._id}>
            <img
              src={iconMap[service.icon] || webDevIcon}
              alt={service.title}
            />
            <h2>{service.title}</h2>
            <p>{service.description}</p>

            {/* ✅ Admin-only Edit/Delete */}
            {isAdmin && (
              <div className="admin-actions">
                <button className="edit-btn" onClick={() => openEditModal(service)}>
                  Edit
                </button>
                <button className="delete-btn" onClick={() => deleteService(service._id)}>
                  Delete
                </button>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* ✅ Add Modal */}
      {showAddModal && (
        <div className="modal">
          <div className="modal-content">
            <h2>Add Service</h2>

            <input
              type="text"
              placeholder="Title"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
            />

            <textarea
              placeholder="Description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            />

            <button onClick={createService}>Save</button>
            <button onClick={() => setShowAddModal(false)}>Cancel</button>
          </div>
        </div>
      )}

      {/* ✅ Edit Modal */}
      {showEditModal && (
        <div className="modal">
          <div className="modal-content">
            <h2>Edit Service</h2>

            <input
              type="text"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
            />

            <textarea
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            />

            <button onClick={updateService}>Update</button>
            <button onClick={() => setShowEditModal(false)}>Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Services;
